use semio_s_artifact_layout_layout_mutations_decisions::simple::SimpleAdvance;
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_s_artifact_layout_layout_mutations_decisions::override_decision::*;

use semio_framework_value::{RetireOwned,retained_clone::RetainedCloneSource};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn source<T:RetireOwned+Sync>(v:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let g=grant(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()});RetainedCloneSource::admit_owned(v,(),g).unwrap_or_else(|(e,_,_)|panic!("{e}")).0}
fn close_source<T:RetireOwned+Sync>(s:&mut RetainedCloneSource<T>){while !s.terminal_is_empty(){let d=s.next_close_demand(256).unwrap();s.close_step(grant(d)).unwrap();}}
fn observe(g:RetainedCloneGrant,f:impl FnOnce()->SimpleAdvance)->SimpleAdvance{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,step.progress.retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress.released_bytes);assert!(step.progress.fits(g));step}
#[test]
fn original_override_admission_and_partial_aliases_use_exact_caller_grants(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let event=decode::<LayoutMutation>(&row["mutation"]);let original=decode::<LayoutSnapshot>(&row["before"]);for cut in std::iter::once(usize::MAX).chain(fixture["cuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize)){let mut m=source(event.clone());let mut b=source(original.clone());let mut owner=OverrideDecision::default();let mut result=None;for turn in 0..cut{assert!(turn<100000);let d=owner.demand(m.borrow(),b.borrow(),256).unwrap();let g=grant(d);assert_eq!(observe(Default::default(),||owner.advance(m.borrow(),b.borrow(),Default::default()).unwrap()).progress,Default::default());for short in[RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g}]{if short==g{continue}assert_eq!(observe(short,||owner.advance(m.borrow(),b.borrow(),short).unwrap()).progress,Default::default())}let step=observe(g,||owner.advance(m.borrow(),b.borrow(),g).unwrap());if step.done{result=Some(step);break}}if cut==usize::MAX{let step=result.expect("bounded original override progress");assert_eq!(step.error.is_none()&&!step.unchanged,row["accepted"].as_bool().unwrap());if let Some(error)=row["error"].as_str(){assert_eq!(step.error,Some(error))}let mut substituted=source(event.clone());assert!(owner.demand(substituted.borrow(),b.borrow(),256).is_err());close_source(&mut substituted)}owner.begin_close();for turn in 0..100000{if owner.terminal_is_empty(){break}assert!(turn<99999);let d=owner.close_demand(256).unwrap();assert_eq!(owner.close_step(Default::default()).unwrap().progress(),Default::default());let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant(d)).unwrap());assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);assert!(step.progress().fits(grant(d)))}assert_eq!(m.borrow().get(),&event);assert_eq!(b.borrow().get(),&original);close_source(&mut m);close_source(&mut b)}}}
